window.MG_LAZY_DATA["data/lazy/courses/v11-hinkley-epr-ef648608487213e7.json"]={sha256:"ef648608487213e7703abc2fc57ece98c76c0928d776f7c3521accdd2aab7778",value:{"id":"v11-hinkley-epr","title":"Hinkley Point C EPR 民用工程","titleEn":"Hinkley Point C EPR civil engineering","category":"energy","subcategory":"energy-nuclear","subcategoryTitle":"民用核能發電","subcategoryTitleEn":"Civil nuclear generation","learningTrack":"energy","learningSubdiscipline":"energy-nuclear","learningTags":["energy","energy-nuclear","hinkley-epr"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-hinkley","v11x-nrc"],"stages":[{"id":"v11-hinkley-epr-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Hinkley Point C EPR 民用工程案例中比較EPR核島與蒸汽迴路與常規島熱電效率，各完成分析及驗證。","descriptionEn":"Analyze and validate epr nuclear/steam loops and conventional-island conversion within the Hinkley Point C EPR civil engineering case.","steps":[{"id":"v11-hinkley-epr-v11-01","order":1,"sequence":1,"title":"核島與汽輪機島邊界：架構分析","titleEn":"Nuclear and turbine-island boundaries: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":[],"objective":"針對EPR核島與蒸汽迴路提出可反駁的核島與汽輪機島邊界模型與驗證紀錄。","objectiveEn":"Produce a falsifiable nuclear and turbine-island boundaries model and evidence record for epr nuclear/steam loops.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識EPR核島與蒸汽迴路。和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。 建立核島與汽輪機島邊界的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。在原創塊圖分開熱流、電流與流體連通。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify epr nuclear/steam loops in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries. Draw the inputs, states, outputs and boundaries of nuclear and turbine-island boundaries, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate heat, electrical and fluid paths in an original block diagram. Record units, undisclosed parameters and model breakdown conditions.","observation":"在原創塊圖分開熱流、電流與流體連通。","observationEn":"Separate heat, electrical and fluid paths in an original block diagram.","failure":"常見誤判：所有核電架構都有完全相同的主次迴路。","failureEn":"Common misconception: All nuclear architectures have identical primary/secondary loops.","check":"提交EPR核島與蒸汽迴路的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for epr nuclear/steam loops.","knowledge":[{"id":"v11-hinkley-epr-v11-01-k1","title":"核島與汽輪機島邊界","titleEn":"Nuclear and turbine-island boundaries","text":"和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。 本課架構對應：EPR核島與蒸汽迴路","textEn":"Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries. Course architecture correspondence: EPR nuclear/steam loops","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"在原創塊圖分開熱流、電流與流體連通。 應逐項保留基準與不確定度；所有核電架構都有完全相同的主次迴路。 是本單元要排除的誤解。","textEn":"Separate heat, electrical and fluid paths in an original block diagram. Retain each reference and uncertainty; reject the misconception: All nuclear architectures have identical primary/secondary loops.","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設民用熱源 400 MWth、熱電效率 0.30、輔機 9 MWe，淨電=400×0.30−9=111.0 MWe；循環排熱約280.0 MW。僅熱平衡，不含反應性、燃料製造或操作整定。","textEn":"Assume civil heat input 400 MWth, efficiency 0.30 and auxiliaries 9 MWe: net power 111.0 MWe; cycle rejection about 280.0 MW. This is heat balance only, without reactivity, fuel manufacture or operating settings.","sourceIds":["v11x-hinkley","v11x-nrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就EPR核島與蒸汽迴路的「核島與汽輪機島邊界」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for nuclear and turbine-island boundaries in epr nuclear/steam loops?","options":["和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。","所有核電架構都有完全相同的主次迴路。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries.","All nuclear architectures have identical primary/secondary loops.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。 在原創塊圖分開熱流、電流與流體連通。","explanationEn":"Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries. Separate heat, electrical and fluid paths in an original block diagram."}},{"id":"v11-hinkley-epr-v11-02","order":2,"sequence":2,"title":"核島與汽輪機島邊界：證據驗證","titleEn":"Nuclear and turbine-island boundaries: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-01"],"objective":"針對EPR核島與蒸汽迴路提出可反駁的核島與汽輪機島邊界模型與驗證紀錄。","objectiveEn":"Produce a falsifiable nuclear and turbine-island boundaries model and evidence record for epr nuclear/steam loops.","instruction":"沿用前一步「核島與汽輪機島邊界」模型，檢查EPR核島與蒸汽迴路的兩個假想案例。在原創塊圖分開熱流、電流與流體連通。 先訂可接受誤差，再比較預測與獨立計算；區分和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous nuclear and turbine-island boundaries model to inspect two hypothetical cases involving epr nuclear/steam loops. Separate heat, electrical and fluid paths in an original block diagram. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"在原創塊圖分開熱流、電流與流體連通。","observationEn":"Separate heat, electrical and fluid paths in an original block diagram.","failure":"常見誤判：所有核電架構都有完全相同的主次迴路。","failureEn":"Common misconception: All nuclear architectures have identical primary/secondary loops.","check":"提交EPR核島與蒸汽迴路的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for epr nuclear/steam loops.","knowledge":[{"id":"v11-hinkley-epr-v11-02-k1","title":"核島與汽輪機島邊界","titleEn":"Nuclear and turbine-island boundaries","text":"和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。 本課架構對應：EPR核島與蒸汽迴路","textEn":"Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries. Course architecture correspondence: EPR nuclear/steam loops","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"在原創塊圖分開熱流、電流與流體連通。 應逐項保留基準與不確定度；所有核電架構都有完全相同的主次迴路。 是本單元要排除的誤解。","textEn":"Separate heat, electrical and fluid paths in an original block diagram. Retain each reference and uncertainty; reject the misconception: All nuclear architectures have identical primary/secondary loops.","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設民用熱源 400 MWth、熱電效率 0.30、輔機 9 MWe，淨電=400×0.30−9=111.0 MWe；循環排熱約280.0 MW。僅熱平衡，不含反應性、燃料製造或操作整定。","textEn":"Assume civil heat input 400 MWth, efficiency 0.30 and auxiliaries 9 MWe: net power 111.0 MWe; cycle rejection about 280.0 MW. This is heat balance only, without reactivity, fuel manufacture or operating settings.","sourceIds":["v11x-hinkley","v11x-nrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就EPR核島與蒸汽迴路的「核島與汽輪機島邊界」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for nuclear and turbine-island boundaries in epr nuclear/steam loops?","options":["所有核電架構都有完全相同的主次迴路。","在原創塊圖分開熱流、電流與流體連通。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["All nuclear architectures have identical primary/secondary loops.","Separate heat, electrical and fluid paths in an original block diagram.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"和平發電以熱源、換熱與汽輪發電連接；壓水、沸水與重水架構的流體邊界不同。 在原創塊圖分開熱流、電流與流體連通。","explanationEn":"Civil generation connects a heat source, transfer and turbine generation; PWR, BWR and heavy-water layouts have different fluid boundaries. Separate heat, electrical and fluid paths in an original block diagram."}},{"id":"v11-hinkley-epr-v11-03","order":3,"sequence":3,"title":"熱循環與淨電效率：架構分析","titleEn":"Thermal cycles and net efficiency: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-02"],"objective":"針對常規島熱電效率提出可反駁的熱循環與淨電效率模型與驗證紀錄。","objectiveEn":"Produce a falsifiable thermal cycles and net efficiency model and evidence record for conventional-island conversion.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識常規島熱電效率。熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。 建立熱循環與淨電效率的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用假想熱平衡分別計算汽輪輸出、輔機與淨電。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify conventional-island conversion in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ. Draw the inputs, states, outputs and boundaries of thermal cycles and net efficiency, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate turbine output, auxiliaries and net power in an assumed balance. Record units, undisclosed parameters and model breakdown conditions.","observation":"用假想熱平衡分別計算汽輪輸出、輔機與淨電。","observationEn":"Separate turbine output, auxiliaries and net power in an assumed balance.","failure":"常見誤判：熱功率增加量必然等於可送電增加量。","failureEn":"Common misconception: Added thermal power necessarily equals added export power.","check":"提交常規島熱電效率的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for conventional-island conversion.","knowledge":[{"id":"v11-hinkley-epr-v11-03-k1","title":"熱循環與淨電效率","titleEn":"Thermal cycles and net efficiency","text":"熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。 本課架構對應：常規島熱電效率","textEn":"Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ. Course architecture correspondence: Conventional-island conversion","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想熱平衡分別計算汽輪輸出、輔機與淨電。 應逐項保留基準與不確定度；熱功率增加量必然等於可送電增加量。 是本單元要排除的誤解。","textEn":"Separate turbine output, auxiliaries and net power in an assumed balance. Retain each reference and uncertainty; reject the misconception: Added thermal power necessarily equals added export power.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就常規島熱電效率的「熱循環與淨電效率」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for thermal cycles and net efficiency in conventional-island conversion?","options":["熱功率增加量必然等於可送電增加量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。"],"optionsEn":["Added thermal power necessarily equals added export power.","Equal case averages rule out spatial, temporal and model errors.","Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ."],"answer":2,"explanation":"熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。 用假想熱平衡分別計算汽輪輸出、輔機與淨電。","explanationEn":"Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ. Separate turbine output, auxiliaries and net power in an assumed balance."}},{"id":"v11-hinkley-epr-v11-04","order":4,"sequence":4,"title":"熱循環與淨電效率：證據驗證","titleEn":"Thermal cycles and net efficiency: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-03"],"objective":"針對常規島熱電效率提出可反駁的熱循環與淨電效率模型與驗證紀錄。","objectiveEn":"Produce a falsifiable thermal cycles and net efficiency model and evidence record for conventional-island conversion.","instruction":"沿用前一步「熱循環與淨電效率」模型，檢查常規島熱電效率的兩個假想案例。用假想熱平衡分別計算汽輪輸出、輔機與淨電。 先訂可接受誤差，再比較預測與獨立計算；區分熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous thermal cycles and net efficiency model to inspect two hypothetical cases involving conventional-island conversion. Separate turbine output, auxiliaries and net power in an assumed balance. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用假想熱平衡分別計算汽輪輸出、輔機與淨電。","observationEn":"Separate turbine output, auxiliaries and net power in an assumed balance.","failure":"常見誤判：熱功率增加量必然等於可送電增加量。","failureEn":"Common misconception: Added thermal power necessarily equals added export power.","check":"提交常規島熱電效率的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for conventional-island conversion.","knowledge":[{"id":"v11-hinkley-epr-v11-04-k1","title":"熱循環與淨電效率","titleEn":"Thermal cycles and net efficiency","text":"熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。 本課架構對應：常規島熱電效率","textEn":"Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ. Course architecture correspondence: Conventional-island conversion","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想熱平衡分別計算汽輪輸出、輔機與淨電。 應逐項保留基準與不確定度；熱功率增加量必然等於可送電增加量。 是本單元要排除的誤解。","textEn":"Separate turbine output, auxiliaries and net power in an assumed balance. Retain each reference and uncertainty; reject the misconception: Added thermal power necessarily equals added export power.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就常規島熱電效率的「熱循環與淨電效率」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for thermal cycles and net efficiency in conventional-island conversion?","options":["用假想熱平衡分別計算汽輪輸出、輔機與淨電。","熱功率增加量必然等於可送電增加量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate turbine output, auxiliaries and net power in an assumed balance.","Added thermal power necessarily equals added export power.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"熱電轉換受熱循環及輔機耗電共同影響；熱功率與淨電功率不同。 用假想熱平衡分別計算汽輪輸出、輔機與淨電。","explanationEn":"Cycle efficiency and auxiliaries affect conversion; thermal and net electrical power differ. Separate turbine output, auxiliaries and net power in an assumed balance."}}]},{"id":"v11-hinkley-epr-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Hinkley Point C EPR 民用工程案例中比較餘熱移除功能與分離支援架構，各完成分析及驗證。","descriptionEn":"Analyze and validate residual-heat removal function and separated support architecture within the Hinkley Point C EPR civil engineering case.","steps":[{"id":"v11-hinkley-epr-v11-05","order":1,"sequence":5,"title":"餘熱與持續冷卻：架構分析","titleEn":"Residual heat and sustained cooling: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-04"],"objective":"針對餘熱移除功能提出可反駁的餘熱與持續冷卻模型與驗證紀錄。","objectiveEn":"Produce a falsifiable residual heat and sustained cooling model and evidence record for residual-heat removal function.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識餘熱移除功能。停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。 建立餘熱與持續冷卻的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。只用給定假想衰減曲線計算熱量及冷卻邊界。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify residual-heat removal function in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture. Draw the inputs, states, outputs and boundaries of residual heat and sustained cooling, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Integrate a supplied assumed decay curve and cooling boundaries only. Record units, undisclosed parameters and model breakdown conditions.","observation":"只用給定假想衰減曲線計算熱量及冷卻邊界。","observationEn":"Integrate a supplied assumed decay curve and cooling boundaries only.","failure":"常見誤判：停止發電後任何排熱需求都立即變成零。","failureEn":"Common misconception: All heat-removal demand immediately vanishes after generation stops.","check":"提交餘熱移除功能的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for residual-heat removal function.","knowledge":[{"id":"v11-hinkley-epr-v11-05-k1","title":"餘熱與持續冷卻","titleEn":"Residual heat and sustained cooling","text":"停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。 本課架構對應：餘熱移除功能","textEn":"Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture. Course architecture correspondence: Residual-heat removal function","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"只用給定假想衰減曲線計算熱量及冷卻邊界。 應逐項保留基準與不確定度；停止發電後任何排熱需求都立即變成零。 是本單元要排除的誤解。","textEn":"Integrate a supplied assumed decay curve and cooling boundaries only. Retain each reference and uncertainty; reject the misconception: All heat-removal demand immediately vanishes after generation stops.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就餘熱移除功能的「餘熱與持續冷卻」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for residual heat and sustained cooling in residual-heat removal function?","options":["停止發電後任何排熱需求都立即變成零。","停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["All heat-removal demand immediately vanishes after generation stops.","Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。 只用給定假想衰減曲線計算熱量及冷卻邊界。","explanationEn":"Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture. Integrate a supplied assumed decay curve and cooling boundaries only."}},{"id":"v11-hinkley-epr-v11-06","order":2,"sequence":6,"title":"餘熱與持續冷卻：證據驗證","titleEn":"Residual heat and sustained cooling: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-05"],"objective":"針對餘熱移除功能提出可反駁的餘熱與持續冷卻模型與驗證紀錄。","objectiveEn":"Produce a falsifiable residual heat and sustained cooling model and evidence record for residual-heat removal function.","instruction":"沿用前一步「餘熱與持續冷卻」模型，檢查餘熱移除功能的兩個假想案例。只用給定假想衰減曲線計算熱量及冷卻邊界。 先訂可接受誤差，再比較預測與獨立計算；區分停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous residual heat and sustained cooling model to inspect two hypothetical cases involving residual-heat removal function. Integrate a supplied assumed decay curve and cooling boundaries only. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"只用給定假想衰減曲線計算熱量及冷卻邊界。","observationEn":"Integrate a supplied assumed decay curve and cooling boundaries only.","failure":"常見誤判：停止發電後任何排熱需求都立即變成零。","failureEn":"Common misconception: All heat-removal demand immediately vanishes after generation stops.","check":"提交餘熱移除功能的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for residual-heat removal function.","knowledge":[{"id":"v11-hinkley-epr-v11-06-k1","title":"餘熱與持續冷卻","titleEn":"Residual heat and sustained cooling","text":"停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。 本課架構對應：餘熱移除功能","textEn":"Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture. Course architecture correspondence: Residual-heat removal function","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"只用給定假想衰減曲線計算熱量及冷卻邊界。 應逐項保留基準與不確定度；停止發電後任何排熱需求都立即變成零。 是本單元要排除的誤解。","textEn":"Integrate a supplied assumed decay curve and cooling boundaries only. Retain each reference and uncertainty; reject the misconception: All heat-removal demand immediately vanishes after generation stops.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就餘熱移除功能的「餘熱與持續冷卻」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for residual heat and sustained cooling in residual-heat removal function?","options":["停止發電後任何排熱需求都立即變成零。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","只用給定假想衰減曲線計算熱量及冷卻邊界。"],"optionsEn":["All heat-removal demand immediately vanishes after generation stops.","Equal case averages rule out spatial, temporal and model errors.","Integrate a supplied assumed decay curve and cooling boundaries only."],"answer":2,"explanation":"停止產熱鏈後仍有餘熱；熱容量與排熱路徑是安全架構分析的一部分。 只用給定假想衰減曲線計算熱量及冷卻邊界。","explanationEn":"Residual heat remains after the production chain stops; thermal storage/removal paths belong in safety architecture. Integrate a supplied assumed decay curve and cooling boundaries only."}},{"id":"v11-hinkley-epr-v11-07","order":3,"sequence":7,"title":"被動與主動支援：架構分析","titleEn":"Passive and active support: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-06"],"objective":"針對分離支援架構提出可反駁的被動與主動支援模型與驗證紀錄。","objectiveEn":"Produce a falsifiable passive and active support model and evidence record for separated support architecture.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識分離支援架構。重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。 建立被動與主動支援的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。繪製熱路徑與單一支援不可用的概念比較。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify separated support architecture in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Gravity/natural circulation can support functions within boundaries and available paths. Draw the inputs, states, outputs and boundaries of passive and active support, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Draw heat paths and a conceptual unavailable-support comparison. Record units, undisclosed parameters and model breakdown conditions.","observation":"繪製熱路徑與單一支援不可用的概念比較。","observationEn":"Draw heat paths and a conceptual unavailable-support comparison.","failure":"常見誤判：被動系統表示無需邊界或失效分析。","failureEn":"Common misconception: Passive systems require no boundary or failure analysis.","check":"提交分離支援架構的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for separated support architecture.","knowledge":[{"id":"v11-hinkley-epr-v11-07-k1","title":"被動與主動支援","titleEn":"Passive and active support","text":"重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。 本課架構對應：分離支援架構","textEn":"Gravity/natural circulation can support functions within boundaries and available paths. Course architecture correspondence: Separated support architecture","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"繪製熱路徑與單一支援不可用的概念比較。 應逐項保留基準與不確定度；被動系統表示無需邊界或失效分析。 是本單元要排除的誤解。","textEn":"Draw heat paths and a conceptual unavailable-support comparison. Retain each reference and uncertainty; reject the misconception: Passive systems require no boundary or failure analysis.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就分離支援架構的「被動與主動支援」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for passive and active support in separated support architecture?","options":["重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。","被動系統表示無需邊界或失效分析。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Gravity/natural circulation can support functions within boundaries and available paths.","Passive systems require no boundary or failure analysis.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。 繪製熱路徑與單一支援不可用的概念比較。","explanationEn":"Gravity/natural circulation can support functions within boundaries and available paths. Draw heat paths and a conceptual unavailable-support comparison."}},{"id":"v11-hinkley-epr-v11-08","order":4,"sequence":8,"title":"被動與主動支援：證據驗證","titleEn":"Passive and active support: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-07"],"objective":"針對分離支援架構提出可反駁的被動與主動支援模型與驗證紀錄。","objectiveEn":"Produce a falsifiable passive and active support model and evidence record for separated support architecture.","instruction":"沿用前一步「被動與主動支援」模型，檢查分離支援架構的兩個假想案例。繪製熱路徑與單一支援不可用的概念比較。 先訂可接受誤差，再比較預測與獨立計算；區分重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous passive and active support model to inspect two hypothetical cases involving separated support architecture. Draw heat paths and a conceptual unavailable-support comparison. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Gravity/natural circulation can support functions within boundaries and available paths.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"繪製熱路徑與單一支援不可用的概念比較。","observationEn":"Draw heat paths and a conceptual unavailable-support comparison.","failure":"常見誤判：被動系統表示無需邊界或失效分析。","failureEn":"Common misconception: Passive systems require no boundary or failure analysis.","check":"提交分離支援架構的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for separated support architecture.","knowledge":[{"id":"v11-hinkley-epr-v11-08-k1","title":"被動與主動支援","titleEn":"Passive and active support","text":"重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。 本課架構對應：分離支援架構","textEn":"Gravity/natural circulation can support functions within boundaries and available paths. Course architecture correspondence: Separated support architecture","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"繪製熱路徑與單一支援不可用的概念比較。 應逐項保留基準與不確定度；被動系統表示無需邊界或失效分析。 是本單元要排除的誤解。","textEn":"Draw heat paths and a conceptual unavailable-support comparison. Retain each reference and uncertainty; reject the misconception: Passive systems require no boundary or failure analysis.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就分離支援架構的「被動與主動支援」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for passive and active support in separated support architecture?","options":["被動系統表示無需邊界或失效分析。","繪製熱路徑與單一支援不可用的概念比較。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Passive systems require no boundary or failure analysis.","Draw heat paths and a conceptual unavailable-support comparison.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"重力與自然循環可提供部分功能，但成功條件仍依設計邊界與可用路徑。 繪製熱路徑與單一支援不可用的概念比較。","explanationEn":"Gravity/natural circulation can support functions within boundaries and available paths. Draw heat paths and a conceptual unavailable-support comparison."}}]},{"id":"v11-hinkley-epr-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Hinkley Point C EPR 民用工程案例中比較複製與廠址界面與設計施工階段追溯，各完成分析及驗證。","descriptionEn":"Analyze and validate replication/site interfaces and design/construction traceability within the Hinkley Point C EPR civil engineering case.","steps":[{"id":"v11-hinkley-epr-v11-09","order":1,"sequence":9,"title":"模組化與共用系統：架構分析","titleEn":"Modularity and shared systems: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-08"],"objective":"針對複製與廠址界面提出可反駁的模組化與共用系統模型與驗證紀錄。","objectiveEn":"Produce a falsifiable modularity and shared systems model and evidence record for replication/site interfaces.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識複製與廠址界面。小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。 建立模組化與共用系統的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。做模塊—共用服務矩陣及共同原因概念圖。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify replication/site interfaces in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies. Draw the inputs, states, outputs and boundaries of modularity and shared systems, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Build a module/shared-service matrix and common-cause concept map. Record units, undisclosed parameters and model breakdown conditions.","observation":"做模塊—共用服務矩陣及共同原因概念圖。","observationEn":"Build a module/shared-service matrix and common-cause concept map.","failure":"常見誤判：模塊數增加就自動消除所有共同故障。","failureEn":"Common misconception: More modules automatically eliminate common failures.","check":"提交複製與廠址界面的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for replication/site interfaces.","knowledge":[{"id":"v11-hinkley-epr-v11-09-k1","title":"模組化與共用系統","titleEn":"Modularity and shared systems","text":"小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。 本課架構對應：複製與廠址界面","textEn":"Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies. Course architecture correspondence: Replication/site interfaces","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"做模塊—共用服務矩陣及共同原因概念圖。 應逐項保留基準與不確定度；模塊數增加就自動消除所有共同故障。 是本單元要排除的誤解。","textEn":"Build a module/shared-service matrix and common-cause concept map. Retain each reference and uncertainty; reject the misconception: More modules automatically eliminate common failures.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就複製與廠址界面的「模組化與共用系統」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for modularity and shared systems in replication/site interfaces?","options":["模塊數增加就自動消除所有共同故障。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。"],"optionsEn":["More modules automatically eliminate common failures.","Equal case averages rule out spatial, temporal and model errors.","Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies."],"answer":2,"explanation":"小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。 做模塊—共用服務矩陣及共同原因概念圖。","explanationEn":"Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies. Build a module/shared-service matrix and common-cause concept map."}},{"id":"v11-hinkley-epr-v11-10","order":2,"sequence":10,"title":"模組化與共用系統：證據驗證","titleEn":"Modularity and shared systems: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-09"],"objective":"針對複製與廠址界面提出可反駁的模組化與共用系統模型與驗證紀錄。","objectiveEn":"Produce a falsifiable modularity and shared systems model and evidence record for replication/site interfaces.","instruction":"沿用前一步「模組化與共用系統」模型，檢查複製與廠址界面的兩個假想案例。做模塊—共用服務矩陣及共同原因概念圖。 先訂可接受誤差，再比較預測與獨立計算；區分小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous modularity and shared systems model to inspect two hypothetical cases involving replication/site interfaces. Build a module/shared-service matrix and common-cause concept map. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"做模塊—共用服務矩陣及共同原因概念圖。","observationEn":"Build a module/shared-service matrix and common-cause concept map.","failure":"常見誤判：模塊數增加就自動消除所有共同故障。","failureEn":"Common misconception: More modules automatically eliminate common failures.","check":"提交複製與廠址界面的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for replication/site interfaces.","knowledge":[{"id":"v11-hinkley-epr-v11-10-k1","title":"模組化與共用系統","titleEn":"Modularity and shared systems","text":"小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。 本課架構對應：複製與廠址界面","textEn":"Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies. Course architecture correspondence: Replication/site interfaces","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"做模塊—共用服務矩陣及共同原因概念圖。 應逐項保留基準與不確定度；模塊數增加就自動消除所有共同故障。 是本單元要排除的誤解。","textEn":"Build a module/shared-service matrix and common-cause concept map. Retain each reference and uncertainty; reject the misconception: More modules automatically eliminate common failures.","sourceIds":["v11x-hinkley","v11x-nrc"]}],"quiz":{"question":"就複製與廠址界面的「模組化與共用系統」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for modularity and shared systems in replication/site interfaces?","options":["做模塊—共用服務矩陣及共同原因概念圖。","模塊數增加就自動消除所有共同故障。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Build a module/shared-service matrix and common-cause concept map.","More modules automatically eliminate common failures.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"小型與大型設備的模塊邊界不同；共用冷卻、電源及施工物流會形成依賴。 做模塊—共用服務矩陣及共同原因概念圖。","explanationEn":"Small/large plants differ in module boundaries; shared cooling, power and logistics create dependencies. Build a module/shared-service matrix and common-cause concept map."}},{"id":"v11-hinkley-epr-v11-11","order":3,"sequence":11,"title":"建造證據與生命週期：架構分析","titleEn":"Construction evidence and lifecycle: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-10"],"objective":"針對設計施工階段追溯提出可反駁的建造證據與生命週期模型與驗證紀錄。","objectiveEn":"Produce a falsifiable construction evidence and lifecycle model and evidence record for design/construction traceability.","instruction":"在「Hinkley Point C EPR 民用工程」的師傅示意與公開來源中，先辨識設計施工階段追溯。設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。 建立建造證據與生命週期的輸入、狀態、輸出及邊界圖；本課重點是複製設計、分離安全支援與工程驗證。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。覈對公開文件支持的階段並標出未完成證據。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify design/construction traceability in the mentor diagram and primary sources for Hinkley Point C EPR civil engineering. Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation. Draw the inputs, states, outputs and boundaries of construction evidence and lifecycle, focusing on design replication, separated safety support and validation. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Record publicly supported stages and evidence still incomplete. Record units, undisclosed parameters and model breakdown conditions.","observation":"覈對公開文件支持的階段並標出未完成證據。","observationEn":"Record publicly supported stages and evidence still incomplete.","failure":"常見誤判：取得設計批准等同每個電廠已商轉。","failureEn":"Common misconception: Design approval means every plant is operating commercially.","check":"提交設計施工階段追溯的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for design/construction traceability.","knowledge":[{"id":"v11-hinkley-epr-v11-11-k1","title":"建造證據與生命週期","titleEn":"Construction evidence and lifecycle","text":"設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。 本課架構對應：設計施工階段追溯","textEn":"Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation. Course architecture correspondence: Design/construction traceability","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"覈對公開文件支持的階段並標出未完成證據。 應逐項保留基準與不確定度；取得設計批准等同每個電廠已商轉。 是本單元要排除的誤解。","textEn":"Record publicly supported stages and evidence still incomplete. Retain each reference and uncertainty; reject the misconception: Design approval means every plant is operating commercially.","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設民用熱源 400 MWth、熱電效率 0.30、輔機 9 MWe，淨電=400×0.30−9=111.0 MWe；循環排熱約280.0 MW。僅熱平衡，不含反應性、燃料製造或操作整定。","textEn":"Assume civil heat input 400 MWth, efficiency 0.30 and auxiliaries 9 MWe: net power 111.0 MWe; cycle rejection about 280.0 MW. This is heat balance only, without reactivity, fuel manufacture or operating settings.","sourceIds":["v11x-hinkley","v11x-nrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就設計施工階段追溯的「建造證據與生命週期」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for construction evidence and lifecycle in design/construction traceability?","options":["取得設計批准等同每個電廠已商轉。","設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Design approval means every plant is operating commercially.","Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。 覈對公開文件支持的階段並標出未完成證據。","explanationEn":"Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation. Record publicly supported stages and evidence still incomplete."}},{"id":"v11-hinkley-epr-v11-12","order":4,"sequence":12,"title":"建造證據與生命週期：證據驗證","titleEn":"Construction evidence and lifecycle: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-hinkley","v11x-nrc"],"prerequisiteIds":["v11-hinkley-epr-v11-11"],"objective":"針對設計施工階段追溯提出可反駁的建造證據與生命週期模型與驗證紀錄。","objectiveEn":"Produce a falsifiable construction evidence and lifecycle model and evidence record for design/construction traceability.","instruction":"沿用前一步「建造證據與生命週期」模型，檢查設計施工階段追溯的兩個假想案例。覈對公開文件支持的階段並標出未完成證據。 先訂可接受誤差，再比較預測與獨立計算；區分設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous construction evidence and lifecycle model to inspect two hypothetical cases involving design/construction traceability. Record publicly supported stages and evidence still incomplete. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"覈對公開文件支持的階段並標出未完成證據。","observationEn":"Record publicly supported stages and evidence still incomplete.","failure":"常見誤判：取得設計批准等同每個電廠已商轉。","failureEn":"Common misconception: Design approval means every plant is operating commercially.","check":"提交設計施工階段追溯的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for design/construction traceability.","knowledge":[{"id":"v11-hinkley-epr-v11-12-k1","title":"建造證據與生命週期","titleEn":"Construction evidence and lifecycle","text":"設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。 本課架構對應：設計施工階段追溯","textEn":"Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation. Course architecture correspondence: Design/construction traceability","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"覈對公開文件支持的階段並標出未完成證據。 應逐項保留基準與不確定度；取得設計批准等同每個電廠已商轉。 是本單元要排除的誤解。","textEn":"Record publicly supported stages and evidence still incomplete. Retain each reference and uncertainty; reject the misconception: Design approval means every plant is operating commercially.","sourceIds":["v11x-hinkley","v11x-nrc"]},{"id":"v11-hinkley-epr-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設民用熱源 400 MWth、熱電效率 0.30、輔機 9 MWe，淨電=400×0.30−9=111.0 MWe；循環排熱約280.0 MW。僅熱平衡，不含反應性、燃料製造或操作整定。","textEn":"Assume civil heat input 400 MWth, efficiency 0.30 and auxiliaries 9 MWe: net power 111.0 MWe; cycle rejection about 280.0 MW. This is heat balance only, without reactivity, fuel manufacture or operating settings.","sourceIds":["v11x-hinkley","v11x-nrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就設計施工階段追溯的「建造證據與生命週期」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for construction evidence and lifecycle in design/construction traceability?","options":["取得設計批准等同每個電廠已商轉。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","覈對公開文件支持的階段並標出未完成證據。"],"optionsEn":["Design approval means every plant is operating commercially.","Equal case averages rule out spatial, temporal and model errors.","Record publicly supported stages and evidence still incomplete."],"answer":2,"explanation":"設計批准、施工、運行與除役是不同階段；QA追溯和監管邊界不能以動畫代替。 覈對公開文件支持的階段並標出未完成證據。","explanationEn":"Design approval, construction, operation and decommissioning differ; animations do not replace QA traceability or regulation. Record publicly supported stages and evidence still incomplete."}}]}],"summary":"以複製設計、分離安全支援與工程驗證解析Hinkley Point C EPR 民用工程：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Hinkley Point C EPR civil engineering through design replication, separated safety support and validation: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"和平民用發電與融合研究的公開熱循環、功能架構及工程證據。核能不包含燃料製備、濃縮、武器、反應性整定或反應爐操作；地熱、風電及水力不提供未經場址驗證的施工／操作參數。算例皆是假想，實機由合格專業團隊依規範負責。","scopeEn":"Public thermal cycles, functional architecture and engineering evidence for peaceful generation/fusion research. Nuclear content excludes fuel production, enrichment, weapons, reactivity settings and reactor operations. Geothermal/wind/hydro supply no unverified construction/operation settings. Examples are hypothetical; qualified professionals govern actual equipment.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假設民用熱源 400 MWth、熱電效率 0.30、輔機 9 MWe，淨電=400×0.30−9=111.0 MWe；循環排熱約280.0 MW。僅熱平衡，不含反應性、燃料製造或操作整定。","textEn":"Assume civil heat input 400 MWth, efficiency 0.30 and auxiliaries 9 MWe: net power 111.0 MWe; cycle rejection about 280.0 MW. This is heat balance only, without reactivity, fuel manufacture or operating settings.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"power","labels":["EPR核島與蒸汽迴路","常規島熱電效率","餘熱移除功能","分離支援架構","複製與廠址界面","設計施工階段追溯"],"labelsEn":["EPR nuclear/steam loops","Conventional-island conversion","Residual-heat removal function","Separated support architecture","Replication/site interfaces","Design/construction traceability"],"original":true,"notToScale":true},"vendorHints":[{"name":"EDF","nameEn":"EDF","url":"https://www.edfenergy.com/energy/nuclear-new-build-projects/hinkley-point-c/reactor","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-hinkley"]},{"name":"U.S. Nuclear Regulatory Commission","nameEn":"U.S. Nuclear Regulatory Commission","url":"https://www.nrc.gov/regulations-legislation/fact-sheets-brochures/backgrounder-on-new-nuclear-plant-designs","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-nrc"]}],"architectureNodes":[["民用熱源","Civil heat source"],["熱傳與蒸汽","Heat transfer and steam"],["汽輪發電機","Turbine-generator"],["冷凝排熱","Condensation/heat removal"],["支援與監測","Support and monitoring"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[4,0],[4,3]],"architectureFamily":"thermal","educationEdition":11,"enrichmentVersion":11}};
